using QuestPDF.Fluent;
using QuestPDF.Helpers;
using QuestPDF.Infrastructure;
namespace AyGest.Wpf.Services;
public sealed class DocumentService
{
 readonly Data.AppDb db; public DocumentService(Data.AppDb db){this.db=db;QuestPDF.Settings.License=LicenseType.Community;}
 public string InvoicePdf(long invoiceId){using var c=db.Open();using var q=c.CreateCommand();q.CommandText="SELECT i.number,i.created_at,i.status,i.subtotal,i.vat,i.total,i.payment_method,COALESCE(cu.name,'Consumidor final'),co.name,co.nuit,co.address,co.phone,co.email FROM invoices i JOIN companies co ON co.id=i.company_id LEFT JOIN customers cu ON cu.id=i.customer_id WHERE i.id=@i";q.Parameters.AddWithValue("@i",invoiceId);using var r=q.ExecuteReader();if(!r.Read())throw new InvalidOperationException("Factura não encontrada.");var number=r.GetString(0);var date=r.GetString(1);var status=r.GetString(2);var subtotal=Convert.ToDecimal(r.GetValue(3));var vat=Convert.ToDecimal(r.GetValue(4));var total=Convert.ToDecimal(r.GetValue(5));var payment=r.IsDBNull(6)?"":r.GetString(6);var customer=r.GetString(7);var company=r.GetString(8);var nuit=r.IsDBNull(9)?"":r.GetString(9);var address=r.IsDBNull(10)?"":r.GetString(10);var phone=r.IsDBNull(11)?"":r.GetString(11);var email=r.IsDBNull(12)?"":r.GetString(12);r.Close();q.Parameters.Clear();q.CommandText="SELECT description,quantity,unit_price,vat_rate,line_total FROM invoice_items WHERE invoice_id=@i ORDER BY id";q.Parameters.AddWithValue("@i",invoiceId);var items=new List<(string,decimal,decimal,decimal,decimal)>();using(var ir=q.ExecuteReader())while(ir.Read())items.Add((ir.GetString(0),Convert.ToDecimal(ir.GetValue(1)),Convert.ToDecimal(ir.GetValue(2)),Convert.ToDecimal(ir.GetValue(3)),Convert.ToDecimal(ir.GetValue(4))));var dir=System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"AyGest","Facturas");Directory.CreateDirectory(dir);var path=System.IO.Path.Combine(dir,$"{number.Replace('/','-')}.pdf");Document.Create(doc=>doc.Page(page=>{page.Size(PageSizes.A4);page.Margin(38);page.Header().Column(x=>{x.Item().Text(company).FontSize(22).Bold();x.Item().Text($"NUIT: {nuit} • {address} • {phone} • {email}").FontSize(9);x.Item().LineHorizontal(1);});page.Content().Column(col=>{col.Spacing(10);col.Item().Row(row=>{row.RelativeItem().Column(a=>{a.Item().Text("FACTURA").FontSize(20).Bold();a.Item().Text(number);a.Item().Text(date);a.Item().Text($"Estado: {status}");});row.RelativeItem().Column(a=>{a.Item().Text("Cliente").Bold();a.Item().Text(customer);a.Item().Text($"Pagamento: {payment}");});});col.Item().Table(t=>{t.ColumnsDefinition(c=>{c.RelativeColumn(5);c.RelativeColumn(1);c.RelativeColumn(2);c.RelativeColumn(1);c.RelativeColumn(2);});t.Header(h=>{h.Cell().Text("Descrição").Bold();h.Cell().Text("Qtd").Bold();h.Cell().Text("Preço").Bold();h.Cell().Text("IVA").Bold();h.Cell().Text("Total").Bold();});foreach(var it in items){t.Cell().Text(it.Item1);t.Cell().Text(it.Item2.ToString("N2"));t.Cell().Text(it.Item3.ToString("N2"));t.Cell().Text(it.Item4.ToString("N0")+"%");t.Cell().Text(it.Item5.ToString("N2"));}});col.Item().AlignRight().Column(a=>{a.Item().Text($"Subtotal: {subtotal:N2} MT");a.Item().Text($"IVA: {vat:N2} MT");a.Item().Text($"TOTAL: {total:N2} MT").FontSize(16).Bold();});});page.Footer().AlignCenter().Text("AyGest • Documento emitido pelo sistema de gestão empresarial");})).GeneratePdf(path);return path;}
}